insert into public.exam_defs(stage,edition,minutes,items) values (1,'2nd',40,'{"parts": [{"id": "yesno", "title": "Part 1 · Yes / No quiz", "instr": "Read each question and answer Yes or No. Press ? if you did not understand. You lose 1 mark for each wrong answer; ? scores 0.", "n": 20, "points": 20, "items": [{"n": 1, "q": "Is the chair high?"}, {"n": 2, "q": "Is Moscow the capital of Russia?"}, {"n": 3, "q": "Is the table behind us?"}, {"n": 4, "q": "Is London the capital of England?"}, {"n": 5, "q": "Am I going to the door?"}, {"n": 6, "q": "Is it right you''re Mr. Brown?"}, {"n": 7, "q": "Are you the teacher?"}, {"n": 8, "q": "Is India in Europe?"}, {"n": 9, "q": "Are there two teachers in this room?"}, {"n": 10, "q": "Is Jack Brown tall?"}, {"n": 11, "q": "Is \"foots\" the plural of \"foot\"?"}, {"n": 12, "q": "Is \"A\" the fifth letter of the alphabet?"}, {"n": 13, "q": "Is \"I\" between H and J?"}, {"n": 14, "q": "20 + 30 equals 50. Is that right?"}, {"n": 15, "q": "Have you got two shoes on your feet?"}, {"n": 16, "q": "Is the letter \"O\" a consonant?"}, {"n": 17, "q": "Is Mr. Brown standing behind the house?"}, {"n": 18, "q": "Are there any chairs on the table?"}, {"n": 19, "q": "Are you answering a question?"}, {"n": 20, "q": "Has Mr. Brown got two legs?"}]}, {"id": "mc", "title": "Part 2 · Circle the correct answer", "instr": "Choose the correct answer.", "points": 20, "items": [{"n": 1, "q": "The box is ____.", "opts": {"a": "small", "b": "large"}}, {"n": 2, "q": "She isn''t a girl, she''s a ____.", "opts": {"a": "man", "b": "woman"}}, {"n": 3, "q": "The house is behind ____.", "opts": {"a": "he", "b": "him"}}, {"n": 4, "q": "I ____ closing the book.", "opts": {"a": "is", "b": "am"}}, {"n": 5, "q": "You ____ reading the book.", "opts": {"a": "isn''t", "b": "aren''t"}}, {"n": 6, "q": "He''s ____ the pen on the floor.", "opts": {"a": "putting", "b": "taking"}}, {"n": 7, "q": "The light is on the ____.", "opts": {"a": "table", "b": "ceiling"}}, {"n": 8, "q": "He isn''t Mr. Brown, he''s ____ Brown.", "opts": {"a": "Anna", "b": "Jack"}}, {"n": 9, "q": "I''m standing on the ____.", "opts": {"a": "room", "b": "floor"}}, {"n": 10, "q": "What ____ doing?", "opts": {"a": "am I", "b": "I am"}}, {"n": 11, "q": "They ____ opening the window.", "opts": {"a": "is", "b": "are"}}, {"n": 12, "q": "I''m putting my shoes on my ____.", "opts": {"a": "foots", "b": "feet"}}, {"n": 13, "q": "____ pictures are there on these walls?", "opts": {"a": "How many", "b": "How much"}}, {"n": 14, "q": "\"E\" is the ____ letter of the alphabet.", "opts": {"a": "fifth", "b": "fifty"}}, {"n": 15, "q": "This pencil is ____ in front of me.", "opts": {"a": "there", "b": "here"}}, {"n": 16, "q": "We ____ sitting on the floor.", "opts": {"a": "isn''t", "b": "aren''t"}}, {"n": 17, "q": "The plural of woman is ____.", "opts": {"a": "women", "b": "womans"}}, {"n": 18, "q": "The letter \"H\" isn''t a ____.", "opts": {"a": "consonant", "b": "vowel"}}, {"n": 19, "q": "The letter \"I\" is ____ the letter B.", "opts": {"a": "after", "b": "before"}}, {"n": 20, "q": "The house is in front of ____.", "opts": {"a": "them", "b": "they"}}]}, {"id": "dictation", "title": "Part 3 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 20}]}') on conflict (stage,edition) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,edition,keys) values (1,'2nd','{"parts": [{"id": "yesno", "points": 20, "keys": {"1": "No", "2": "Yes", "3": "No", "4": "Yes", "5": "No", "6": "No", "7": "No", "8": "No", "9": "No", "10": "No", "11": "No", "12": "No", "13": "Yes", "14": "Yes", "15": "Yes", "16": "No", "17": "No", "18": "No", "19": "Yes", "20": "Yes"}}, {"id": "mc", "points": 20, "keys": {"1": "a", "2": "b", "3": "b", "4": "b", "5": "b", "6": "a", "7": "b", "8": "b", "9": "b", "10": "a", "11": "b", "12": "b", "13": "a", "14": "a", "15": "b", "16": "b", "17": "a", "18": "b", "19": "a", "20": "a"}}, {"id": "dictation", "points": 20, "text": "What''s this? It''s a light. The table is not short; it is long. A village is small, but a city is large. Where is the light? It''s on the ceiling. Mr. White is standing in front of the house, but Mrs. Green is sitting behind it. He is not Mr. Low; he''s Mr. Black. What am I doing? You are taking the book from the table, opening it, and putting it on the floor. Who is she?"}]}') on conflict (stage,edition) do update set keys=excluded.keys;
insert into public.exam_defs(stage,edition,minutes,items) values (3,'2nd',40,'{"parts": [{"id": "yesno", "title": "Part 1 · Yes / No quiz", "instr": "Read each question and answer Yes or No. Press ? if you did not understand. You lose 1 mark for each wrong answer; ? scores 0.", "n": 20, "points": 20, "items": [{"n": 1, "q": "Do we say good afternoon to people between 5pm and 10pm?"}, {"n": 2, "q": "Is your nationality British?"}, {"n": 3, "q": "Is \"the longest\" the superlative of \"long\"?"}, {"n": 4, "q": "Has each chair got four legs?"}, {"n": 5, "q": "Do you leave your books in the classroom after the lesson?"}, {"n": 6, "q": "Can you lift the table with your little finger?"}, {"n": 7, "q": "Is autumn one of the four seasons of the year?"}, {"n": 8, "q": "Are you younger than your mother?"}, {"n": 9, "q": "Is it cool in spring?"}, {"n": 10, "q": "Do I say goodbye to you at the beginning of the lesson?"}, {"n": 11, "q": "Must you study a lot if you want to learn a language well?"}, {"n": 12, "q": "Do we nod our heads when we say NO?"}, {"n": 13, "q": "Can you lift the table with your little finger?"}, {"n": 14, "q": "Does Thursday precede Wednesday?"}, {"n": 15, "q": "Is your stomach empty after a large meal?"}, {"n": 16, "q": "Is it warm in autumn?"}, {"n": 17, "q": "Do people generally drink less milk than water?"}, {"n": 18, "q": "Can we play tennis without a ball?"}, {"n": 19, "q": "Do we add the letters \"ed\" to form the past tense of regular verbs?"}, {"n": 20, "q": "Is it a bad idea to go to England if you want to learn English well?"}]}, {"id": "mc", "title": "Part 2 · Circle the correct answer", "instr": "Choose the correct answer.", "points": 20, "items": [{"n": 1, "q": "The ____ of beautiful is \"the most beautiful\".", "opts": {"a": "superlative", "b": "comparative"}}, {"n": 2, "q": "This month is May. Next month will be ____.", "opts": {"a": "April", "b": "June"}}, {"n": 3, "q": "We say: it''s ____.", "opts": {"a": "twenty to four a.m.", "b": "three forty a.m."}}, {"n": 4, "q": "We say ____ to people between about 5p.m. and 10p.m.", "opts": {"a": "good afternoon", "b": "good evening"}}, {"n": 5, "q": "____ country is the opposite of the town.", "opts": {"a": "A", "b": "The"}}, {"n": 6, "q": "She ____ with her parents.", "opts": {"a": "lives", "b": "leaves"}}, {"n": 7, "q": "This piece of paper is ____ than the table.", "opts": {"a": "light", "b": "lighter"}}, {"n": 8, "q": "____ each student got two eyes?", "opts": {"a": "Have", "b": "Has"}}, {"n": 9, "q": "An onion is a ____.", "opts": {"a": "fruit", "b": "vegetable"}}, {"n": 10, "q": "I sometimes ____ food on my plate after a meal.", "opts": {"a": "live", "b": "leave"}}, {"n": 11, "q": "I ____ in São Paulo.", "opts": {"a": "live", "b": "leave"}}, {"n": 12, "q": "She only has breakfast and lunch. She eats ____ a day.", "opts": {"a": "twice", "b": "once"}}, {"n": 13, "q": "Tuesday ____ Wednesday.", "opts": {"a": "precedes", "b": "follows"}}, {"n": 14, "q": "I''m 24 and my brother is 30. I can say that my brother is ____ than me.", "opts": {"a": "younger", "b": "older"}}, {"n": 15, "q": "I''m 24, my brother is 30, and my sister is 32. I''m the ____ in my family.", "opts": {"a": "oldest", "b": "youngest"}}, {"n": 16, "q": "We ____ our coats when we go out in winter.", "opts": {"a": "put on", "b": "take off"}}, {"n": 17, "q": "____ is either in March or April.", "opts": {"a": "Easter", "b": "Christmas"}}, {"n": 18, "q": "I sit ____ John during the lesson.", "opts": {"a": "besides", "b": "beside"}}, {"n": 19, "q": "Finland is one of the ____ countries in the world.", "opts": {"a": "hottest", "b": "coldest"}}, {"n": 20, "q": "I don''t eat ____ food for dinner as I do for lunch.", "opts": {"a": "as much", "b": "as many"}}]}, {"id": "dictation", "title": "Part 3 · Dictation", "instr": "Your teacher reads the dictation. Write what you hear in the box.", "points": 20}]}') on conflict (stage,edition) do update set minutes=excluded.minutes, items=excluded.items;
insert into public.exam_keys(stage,edition,keys) values (3,'2nd','{"parts": [{"id": "yesno", "points": 20, "keys": {"1": "No", "2": "No", "3": "Yes", "4": "Yes", "5": "No", "6": "No", "7": "Yes", "8": "Yes", "9": "No", "10": "No", "11": "Yes", "12": "No", "13": "No", "14": "No", "15": "No", "16": "No", "17": "Yes", "18": "No", "19": "Yes", "20": "No"}}, {"id": "mc", "points": 20, "keys": {"1": "a", "2": "b", "3": "b", "4": "b", "5": "b", "6": "a", "7": "b", "8": "b", "9": "b", "10": "b", "11": "a", "12": "a", "13": "a", "14": "b", "15": "b", "16": "a", "17": "a", "18": "b", "19": "b", "20": "a"}}, {"id": "dictation", "points": 20, "text": "We eat with a knife, fork and spoon. I only put a little salt and pepper on my food. I''ve got less money than the bank. The names of the four seasons of the year are spring, summer, autumn and winter. Sometimes the students precede the teacher into the classroom."}]}') on conflict (stage,edition) do update set keys=excluded.keys;
